import java.util.*; import java.io.*; public class Main { public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); String line = br.readLine(); if (line == null) return; StringTokenizer st = new StringTokenizer(line); int count = 0; while (st.hasMoreTokens()) { int p = Integer.parseInt(st.nextToken()); if (p >= 10) { count++; } } System.out.println(count); } }